-- Gaps, borders, opacity, blur and layout; colors and opacity follow the mode.

local state = require("modules.mode")
local focus, solid = state.focus, state.solid

-- Colors generated by matugen into ~/.config/hypr/colors.lua (not tracked).
-- The fallback keeps the session usable if that file is missing or invalid.
local colors = {
    primary         = "rgba(00f5ffcc)",
    tertiary        = "rgba(ff007fcc)",
    outline         = "rgba(8e9099ff)",
    outline_variant = "rgba(24273aaa)",
}
local ok, generated = pcall(function()
    return dofile(os.getenv("HOME") .. "/.config/hypr/colors.lua")
end)
if ok and type(generated) == "table" then
    colors = generated
end

hl.config({
    general = {
        gaps_in  = 4,
        gaps_out = 8,
        border_size = 2,

        col = {
            active_border   = focus and colors.outline
                              or { colors = { colors.primary, colors.tertiary }, angle = 45 },
            inactive_border = colors.outline_variant,
        },

        resize_on_border = true,
        allow_tearing    = false,
        layout           = "dwindle",
    },

    decoration = {
        rounding        = 12,
        rounding_power  = 2,

        active_opacity   = solid and 1.0 or 0.97,
        inactive_opacity = solid and 1.0 or 0.90,

        shadow = {
            enabled      = true,
            range        = 14,
            render_power = 2,
            color        = 0x40000000,
        },

        blur = {
            enabled           = true,
            size              = 5,
            passes            = 2,
            new_optimizations = true,
            vibrancy          = 0.15,
            ignore_opacity    = false,
        },
    },

    misc = {
        force_default_wallpaper = 2,
        disable_hyprland_logo   = true,
        vrr = 0,
        -- Lets a lock screen restarted from a TTY take over after a crash
        allow_session_lock_restore = true,
    },

    cursor = {
        no_hardware_cursors  = true,
        enable_hyprcursor    = true,
        sync_gsettings_theme = true,
    },
})

hl.config({
    dwindle = {
        preserve_split = true,
    },
})

-- Blur behind the shell surfaces (the bar only in browsing mode);
-- ignore_alpha keeps the transparent gaps between panels unblurred.
local blurred = { "quickshell-notifications", "quickshell-controlcenter", "quickshell-calendar", "quickshell-menu", "quickshell-osd" }
if not focus then table.insert(blurred, "quickshell-bar") end
for _, namespace in ipairs(blurred) do
    hl.layer_rule({
        name         = "blur-" .. namespace,
        match        = { namespace = "^" .. namespace .. "$" },
        blur         = true,
        ignore_alpha = 0.2,
    })
end
